import React, { useState, useEffect } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { bookingAPI, reviewAPI } from '../services/api';
import { useAuth } from '../context/AuthContext';

const CreateReview = () => {
  const { id } = useParams(); // id de la salle
  const navigate = useNavigate();
  const { user } = useAuth();
  
  const [bookings, setBookings] = useState([]);
  const [selectedBooking, setSelectedBooking] = useState('');
  const [reviewData, setReviewData] = useState({
    rating: 5,
    comment: ''
  });
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!user) {
      navigate('/login');
      return;
    }
    
    fetchUserBookings();
  }, [id, user, navigate]);

  const fetchUserBookings = async () => {
    setLoading(true);
    try {
      const response = await bookingAPI.getMyBookings();
      // Filtrer pour ne garder que les réservations terminées pour cette salle
      const filteredBookings = (response.data.bookings || []).filter(booking => 
        booking.room_id === parseInt(id) && 
        booking.status === 'completed' &&
        !booking.has_review // Supposons que tu aies un champ has_review
      );
      
      setBookings(filteredBookings);
      
      // Si une seule réservation, la sélectionner automatiquement
      if (filteredBookings.length === 1) {
        setSelectedBooking(filteredBookings[0].id.toString());
      }
    } catch (error) {
      console.error('Erreur chargement réservations:', error);
      setError('Impossible de charger vos réservations');
    } finally {
      setLoading(false);
    }
  };

  const handleChange = (e) => {
    setReviewData({
      ...reviewData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    if (!selectedBooking) {
      setError('Veuillez sélectionner une réservation');
      return;
    }

    if (!reviewData.rating) {
      setError('Veuillez donner une note');
      return;
    }

    try {
      const payload = {
        booking_id: parseInt(selectedBooking),
        rating: parseInt(reviewData.rating),
        comment: reviewData.comment
      };

      const response = await reviewAPI.create(payload);
      
      if (response.success) {
        setSuccess('Avis publié avec succès !');
        setTimeout(() => {
          navigate(`/rooms/${id}`);
        }, 2000);
      }
    } catch (error) {
      setError(error.message || 'Erreur lors de la publication de l\'avis');
    }
  };

  if (!user) {
    return (
      <div className="main-content">
        <div className="card">
          <h2>Accès non autorisé</h2>
          <p>Vous devez être connecté pour laisser un avis.</p>
          <Link to="/login" className="btn btn-primary">
            Se connecter
          </Link>
        </div>
      </div>
    );
  }

  return (
    <div className="main-content">
      <div className="card">
        <h1>📝 Laisser un avis</h1>
        <p>Partagez votre expérience concernant cette salle</p>
      </div>

      <div className="card">
        {error && (
          <div className="alert alert-error">
            {error}
          </div>
        )}
        
        {success && (
          <div className="alert alert-success">
            {success}
          </div>
        )}

        {loading ? (
          <p>Chargement de vos réservations...</p>
        ) : bookings.length === 0 ? (
          <div>
            <p>Vous ne pouvez pas laisser d'avis pour cette salle car :</p>
            <ul>
              <li>Vous n'avez pas encore réservé cette salle</li>
              <li>Ou vos réservations ne sont pas encore terminées</li>
              <li>Ou vous avez déjà laissé un avis pour cette salle</li>
            </ul>
            <Link to={`/rooms/${id}`} className="btn btn-primary">
              Retour à la salle
            </Link>
          </div>
        ) : (
          <form onSubmit={handleSubmit}>
            <div className="form-group">
              <label className="form-label">Sélectionner une réservation</label>
              <select
                name="booking_id"
                className="form-input"
                value={selectedBooking}
                onChange={(e) => setSelectedBooking(e.target.value)}
                required
              >
                <option value="">Choisir une réservation</option>
                {bookings.map(booking => (
                  <option key={booking.id} value={booking.id}>
                    Réservation #{booking.id} - {new Date(booking.start_datetime).toLocaleDateString('fr-FR')}
                  </option>
                ))}
              </select>
            </div>

            <div className="form-group">
              <label className="form-label">Note (1 à 5 étoiles)</label>
              <div className="rating-stars">
                {[1, 2, 3, 4, 5].map(star => (
                  <button
                    key={star}
                    type="button"
                    className={`star-btn ${reviewData.rating >= star ? 'active' : ''}`}
                    onClick={() => setReviewData({...reviewData, rating: star})}
                  >
                    ⭐
                  </button>
                ))}
              </div>
              <input
                type="range"
                name="rating"
                min="1"
                max="5"
                value={reviewData.rating}
                onChange={handleChange}
                className="form-input"
                style={{ width: '100%' }}
              />
              <small style={{ color: '#666' }}>
                Sélectionné: {reviewData.rating} étoile(s)
              </small>
            </div>

            <div className="form-group">
              <label className="form-label">Commentaire (optionnel)</label>
              <textarea
                name="comment"
                className="form-input"
                value={reviewData.comment}
                onChange={handleChange}
                rows="4"
                placeholder="Partagez votre expérience..."
                maxLength="500"
              />
              <small style={{ color: '#666' }}>
                {reviewData.comment.length}/500 caractères
              </small>
            </div>

            <div className="form-buttons">
              <button type="submit" className="btn btn-primary">
                Publier l'avis
              </button>
              <Link to={`/rooms/${id}`} className="btn btn-secondary">
                Annuler
              </Link>
            </div>
          </form>
        )}
      </div>
    </div>
  );
};

export default CreateReview;
